-- DRAKMOR chat, execute once in Supabase SQL Editor.
create table if not exists public.chat_messages (id bigint generated always as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, channel text not null check(channel in ('global','guild')), guild_id bigint references public.guilds(id) on delete cascade, body text not null check(char_length(body) between 1 and 300), created_at timestamptz not null default now(), check((channel='global' and guild_id is null) or (channel='guild' and guild_id is not null)));
create index if not exists chat_messages_channel_idx on public.chat_messages(channel,guild_id,created_at desc);
alter table public.chat_messages enable row level security;
revoke all on public.chat_messages from anon,authenticated;
create or replace function public.chat_read(p_channel text default 'global') returns table(id bigint,hero_name text,body text,created_at timestamptz) language plpgsql security definer set search_path='' as $$declare v_guild bigint;begin if auth.uid() is null then raise exception 'Pieslēdzies kontam';end if;if p_channel not in ('global','guild') then raise exception 'Nepareizs kanāls';end if;if p_channel='guild' then select guild_id into v_guild from public.guild_members where user_id=auth.uid();if v_guild is null then return;end if;end if;return query select c.id,coalesce(nullif(left(h.state->>'name',30),''),'Varonis')::text,c.body,c.created_at from (select * from public.chat_messages m where m.channel=p_channel and (p_channel='global' or m.guild_id=v_guild) order by m.created_at desc limit 60) c left join public.hero_saves h on h.user_id=c.user_id order by c.created_at asc;end$$;
create or replace function public.chat_send(p_channel text,p_body text) returns void language plpgsql security definer set search_path='' as $$declare v_guild bigint;begin if auth.uid() is null then raise exception 'Pieslēdzies kontam';end if;if p_channel not in ('global','guild') then raise exception 'Nepareizs kanāls';end if;if length(trim(coalesce(p_body,''))) not between 1 and 300 then raise exception 'Ziņai jābūt 1–300 simboliem';end if;if exists(select 1 from public.chat_messages where user_id=auth.uid() and created_at>now()-interval '3 seconds') then raise exception 'Pagaidi 3 sekundes pirms nākamās ziņas';end if;if p_channel='guild' then select guild_id into v_guild from public.guild_members where user_id=auth.uid();if v_guild is null then raise exception 'Tu neesi ģildē';end if;end if;insert into public.chat_messages(user_id,channel,guild_id,body) values(auth.uid(),p_channel,v_guild,trim(p_body));end$$;
revoke all on function public.chat_read(text),public.chat_send(text,text) from public,anon;
grant execute on function public.chat_read(text),public.chat_send(text,text) to authenticated;
